mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, time, urllib.request, urllib.error, sys
BASE = "http://localhost:8080"
tok = None
log = []
def get_token():
    global tok
    r = urllib.request.urlopen(urllib.request.Request(BASE + "/token", method="POST", data=b""))
    tok = json.load(r)["token"]
    log.append(("token", tok))
def call(path, allow404=False):
    attempts = 0
    while True:
        attempts += 1
        if tok is None: get_token()
        req = urllib.request.Request(BASE + path, headers={"Authorization": "Bearer " + tok})
        try:
            r = urllib.request.urlopen(req, timeout=30)
            body = r.read()
            try:
                return json.loads(body)
            except Exception as e:
                log.append(("badjson", path, body[:200].decode(errors="replace"))); time.sleep(0.5); continue
        except urllib.error.HTTPError as e:
            body = e.read()[:300].decode(errors="replace")
            hdrs = dict(e.headers)
            log.append((e.code, path, body, {k: v for k, v in hdrs.items() if k.lower() not in ("date","server","content-length","content-type")}))
            if e.code == 401 or e.code == 403:
                get_token(); continue
            if e.code == 429:
                ra = e.headers.get("Retry-After")
                try: w = float(ra)
                except: w = 2.0
                time.sleep(w + 0.1); continue
            if e.code == 404 and allow404:
                return None
            time.sleep(1); continue
        except Exception as e:
            log.append(("exc", path, repr(e))); time.sleep(1); continue

pages = {}
path = "/orders?page=1"
while path:
    d = call(path)
    pages[d["page"]] = d
    path = d["next"]
json.dump(pages, open("/tmp/recon/pages.json", "w"))
cids = sorted({o["customer_id"] for p in pages.values() for o in p["items"]})
custs = {}
for c in cids:
    custs[c] = call("/customers/" + c, allow404=True)
json.dump(custs, open("/tmp/recon/custs.json", "w"))
json.dump(log, open("/tmp/recon/log.json", "w"), default=str)
print(len(pages), "pages;", len(cids), "customers;", len(log), "log entries")
EOF
python3 -I /tmp/recon/fetch.py

